def comps(g,color=None):
    seen=set(); out=[]
    for i,row in enumerate(g):
        for j,x in enumerate(row):
            if ((color is None or x==color) and (i,j) not in seen):
                st=[(i,j)]; comp=[]; seen.add((i,j))
                while st:
                    p=st.pop(); comp.append(p)
                    for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
                        q=(p[0]+di,p[1]+dj)
                        if 0<=q[0]<len(g) and 0<=q[1]<len(g[0]) and (color is None or g[q[0]][q[1]]==x) and q not in seen:
                            seen.add(q); st.append(q)
                out.append((x,comp))
    return out
